ng>${o.unique_signed_in_buyers}</strong><span>Signed-in buyers</span></div><div class="metric"><strong>${o.repeat_buyers}</strong><span>Repeat buyers</span></div><div class="metric"><strong>${o.recommendation_runs}</strong><span>Consultations with recommendations</span></div></div>${promo}<div class="grid">${list('Top categories',d.categories,r=>r.label,r=>r.consultations)}${list('Most requested capabilities',d.requirements,r=>r.label,r=>`${r.demand_count} requests · ${r.must_have_count} must-have`)}${list('Most recommended products',d.products,r=>r.name,r=>`${r.recommendation_count} appearances · ${r.top_rank_count} #1`)}${list('Most viewed products',d.views,r=>r.name,r=>r.view_count)}${list('Most viewed comparisons',d.comparisons,r=>`${r.product_a} vs ${r.product_b}`,r=>r.comparison_count)}${list('Countries',d.countries,r=>r.label,r=>r.consultations)}${list('Industries',d.industries,r=>r.label,r=>r.consultations)}${list('Company sizes',d.companySizes,r=>r.label,r=>r.consultations)}${list('Catalog gaps / unmapped demand',d.unmapped,r=>r.label,r=>`${r.demand_count} · ${r.status}`)}</div><div class="note">Buyer and promotion analytics are aggregate-only. Private consultation text, emails, session tokens and identifiers are not exposed here.</div>`}).catch(e=>app.innerHTML=`<section class="panel">${esc(e.message)}</section>`);
